"""Number of Islands — flood fill every unvisited land cell.

Sinking each island as it is counted avoids a separate visited matrix.

Time: O(m*n)   Space: O(m*n) worst-case stack
"""
from typing import List


class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if not grid:
            return 0
        m, n = len(grid), len(grid[0])

        def sink(i: int, j: int) -> None:
            stack = [(i, j)]
            while stack:
                x, y = stack.pop()
                if 0 <= x < m and 0 <= y < n and grid[x][y] == "1":
                    grid[x][y] = "0"
                    stack.extend(((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)))

        islands = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == "1":
                    islands += 1
                    sink(i, j)
        return islands
